Translate the following Python 3 code to Java 8 code. The code reads and writes I/O from the console. Your translated code should have the exact same functionality as the given code, meaning that it should have the same output for any given input.
Print your translated code and also the confidence score you give to your translation. The confidence score should be a number between 0 and 1. The format of the output should be:
<translated_code>
<your_translated_code>
</translated_code>
<confidence>
<your_confidence_score>
</confidence>
Do not provide any other text or markdown fences.

Here is the original Python 3 code you have to translate:
<original_code>
"""
Codeforces Contest 287 Div 2 Problem C - Variant 5

Author  : chaotic_iak
Language: Python 3.4.2
"""

def main():
    h, n = read()
    n = n - 1
    binary_string = bin(n)[2:]
    binary_string = "0" * (h - len(binary_string)) + binary_string

    result_string = ""
    for index in range(h):
        if index > 0 and binary_string[index - 1] == "0":
            result_string += "1" if binary_string[index] == "0" else "0"
        else:
            result_string += binary_string[index]

    total_value = 0
    for index in range(h):
        total_value += 1
        if result_string[index] == "1":
            total_value += 2 ** (h - index) - 1
    print(total_value)

def read(mode=2):
    line_input = input().strip()
    if mode == 0:
        return line_input
    elif mode == 1:
        return line_input.split()
    elif mode == 2:
        return list(map(int, line_input.split()))

def write(s="\n"):
    if s is None:
        s = ""
    if isinstance(s, list):
        s = " ".join(map(str, s))
    print(str(s), end="")

write(main())
</original_code>
